import 'dart:convert';
import 'package:equatable/equatable.dart';

/// Enumerates the primitive drawing operations supported by the display list pipeline.
enum DrawCommandType {
  text,
  image,
  rect,
  rule,
}

/// Base abstract class for all deterministic visual drawing commands generated by
/// the page composition engine.
sealed class DrawCommand extends Equatable {
  final DrawCommandType type;

  const DrawCommand(this.type);

  /// Serializes the command to a JSON-compatible map.
  Map<String, dynamic> toMap();

  /// Deserializes a polymorphic [DrawCommand] from a map.
  static DrawCommand fromMap(Map<String, dynamic> map) {
    final typeStr = map['type'] as String?;
    switch (typeStr) {
      case 'text':
        return DrawTextCommand.fromMap(map);
      case 'image':
        return DrawImageCommand.fromMap(map);
      case 'rect':
        return DrawRectCommand.fromMap(map);
      case 'rule':
        return DrawRuleCommand.fromMap(map);
      default:
        throw ArgumentError('Unknown DrawCommand type: $typeStr');
    }
  }

  /// Deserializes a polymorphic [DrawCommand] from a JSON string.
  static DrawCommand fromJson(String source) =>
      fromMap(jsonDecode(source) as Map<String, dynamic>);

  /// Serializes the command to a JSON string.
  String toJson() => jsonEncode(toMap());
}

/// Command instructing the rasterizer to draw text at an exact absolute coordinate.
class DrawTextCommand extends DrawCommand {
  final String text;
  final double x;
  final double y;
  final String fontFamily;
  final double fontSize;
  final bool isBold;
  final bool isItalic;
  final String color; // Hex color string, e.g. '#1a1a1a' or '#000000'
  final double wordSpacing; // Added space between words for justified typesetting
  final double letterSpacing; // Letter tracking adjustment
  final String textAlign; // 'left', 'center', 'right', 'justify'

  const DrawTextCommand({
    required this.text,
    required this.x,
    required this.y,
    this.fontFamily = 'Arimo',
    this.fontSize = 28.0,
    this.isBold = false,
    this.isItalic = false,
    this.color = '#1a1a1a',
    this.wordSpacing = 0.0,
    this.letterSpacing = 0.0,
    this.textAlign = 'left',
  }) : super(DrawCommandType.text);

  @override
  Map<String, dynamic> toMap() {
    return {
      'type': 'text',
      'text': text,
      'x': x,
      'y': y,
      'fontFamily': fontFamily,
      'fontSize': fontSize,
      'isBold': isBold,
      'isItalic': isItalic,
      'color': color,
      'wordSpacing': wordSpacing,
      'letterSpacing': letterSpacing,
      'textAlign': textAlign,
    };
  }

  factory DrawTextCommand.fromMap(Map<String, dynamic> map) {
    return DrawTextCommand(
      text: (map['text'] ?? '').toString(),
      x: (map['x'] as num?)?.toDouble() ?? 0.0,
      y: (map['y'] as num?)?.toDouble() ?? 0.0,
      fontFamily: (map['fontFamily'] ?? 'Arimo').toString(),
      fontSize: (map['fontSize'] as num?)?.toDouble() ?? 28.0,
      isBold: map['isBold'] == true,
      isItalic: map['isItalic'] == true,
      color: (map['color'] ?? '#1a1a1a').toString(),
      wordSpacing: (map['wordSpacing'] as num?)?.toDouble() ?? 0.0,
      letterSpacing: (map['letterSpacing'] as num?)?.toDouble() ?? 0.0,
      textAlign: (map['textAlign'] ?? 'left').toString(),
    );
  }

  @override
  List<Object?> get props => [
    type,
    text,
    x,
    y,
    fontFamily,
    fontSize,
    isBold,
    isItalic,
    color,
    wordSpacing,
    letterSpacing,
    textAlign,
  ];
}

/// Command instructing the rasterizer to paint a remote image at an exact bounding rectangle.
class DrawImageCommand extends DrawCommand {
  final String url;
  final double x;
  final double y;
  final double width;
  final double height;
  final String fit; // 'contain', 'cover', 'fill'

  const DrawImageCommand({
    required this.url,
    required this.x,
    required this.y,
    required this.width,
    required this.height,
    this.fit = 'contain',
  }) : super(DrawCommandType.image);

  @override
  Map<String, dynamic> toMap() {
    return {
      'type': 'image',
      'url': url,
      'x': x,
      'y': y,
      'width': width,
      'height': height,
      'fit': fit,
    };
  }

  factory DrawImageCommand.fromMap(Map<String, dynamic> map) {
    return DrawImageCommand(
      url: (map['url'] ?? '').toString(),
      x: (map['x'] as num?)?.toDouble() ?? 0.0,
      y: (map['y'] as num?)?.toDouble() ?? 0.0,
      width: (map['width'] as num?)?.toDouble() ?? 0.0,
      height: (map['height'] as num?)?.toDouble() ?? 0.0,
      fit: (map['fit'] ?? 'contain').toString(),
    );
  }

  @override
  List<Object?> get props => [type, url, x, y, width, height, fit];
}

/// Command instructing the rasterizer to draw a filled or outlined rectangle.
class DrawRectCommand extends DrawCommand {
  final double x;
  final double y;
  final double width;
  final double height;
  final String? fillColor; // Hex color string, or null if transparent
  final String? borderColor; // Hex color string, or null if borderless
  final double borderWidth;

  const DrawRectCommand({
    required this.x,
    required this.y,
    required this.width,
    required this.height,
    this.fillColor,
    this.borderColor,
    this.borderWidth = 0.0,
  }) : super(DrawCommandType.rect);

  @override
  Map<String, dynamic> toMap() {
    return {
      'type': 'rect',
      'x': x,
      'y': y,
      'width': width,
      'height': height,
      if (fillColor != null) 'fillColor': fillColor,
      if (borderColor != null) 'borderColor': borderColor,
      'borderWidth': borderWidth,
    };
  }

  factory DrawRectCommand.fromMap(Map<String, dynamic> map) {
    return DrawRectCommand(
      x: (map['x'] as num?)?.toDouble() ?? 0.0,
      y: (map['y'] as num?)?.toDouble() ?? 0.0,
      width: (map['width'] as num?)?.toDouble() ?? 0.0,
      height: (map['height'] as num?)?.toDouble() ?? 0.0,
      fillColor: map['fillColor']?.toString(),
      borderColor: map['borderColor']?.toString(),
      borderWidth: (map['borderWidth'] as num?)?.toDouble() ?? 0.0,
    );
  }

  @override
  List<Object?> get props => [
    type,
    x,
    y,
    width,
    height,
    fillColor,
    borderColor,
    borderWidth,
  ];
}

/// Command instructing the rasterizer to stroke a line/rule between two coordinates.
class DrawRuleCommand extends DrawCommand {
  final double x1;
  final double y1;
  final double x2;
  final double y2;
  final String strokeColor;
  final double strokeWidth;

  const DrawRuleCommand({
    required this.x1,
    required this.y1,
    required this.x2,
    required this.y2,
    this.strokeColor = '#000000',
    this.strokeWidth = 1.0,
  }) : super(DrawCommandType.rule);

  @override
  Map<String, dynamic> toMap() {
    return {
      'type': 'rule',
      'x1': x1,
      'y1': y1,
      'x2': x2,
      'y2': y2,
      'strokeColor': strokeColor,
      'strokeWidth': strokeWidth,
    };
  }

  factory DrawRuleCommand.fromMap(Map<String, dynamic> map) {
    return DrawRuleCommand(
      x1: (map['x1'] as num?)?.toDouble() ?? 0.0,
      y1: (map['y1'] as num?)?.toDouble() ?? 0.0,
      x2: (map['x2'] as num?)?.toDouble() ?? 0.0,
      y2: (map['y2'] as num?)?.toDouble() ?? 0.0,
      strokeColor: (map['strokeColor'] ?? '#000000').toString(),
      strokeWidth: (map['strokeWidth'] as num?)?.toDouble() ?? 1.0,
    );
  }

  @override
  List<Object?> get props => [
    type,
    x1,
    y1,
    x2,
    y2,
    strokeColor,
    strokeWidth,
  ];
}

/// Represents a single physical page canvas (e.g. 2000x3200) containing an ordered
/// sequence of drawing commands ready for rendering or preview.
class PageLayoutSheet extends Equatable {
  final int pageNumber;
  final int width;
  final int height;
  final List<DrawCommand> commands;

  /// Aggregated plain/markdown text present on this specific page.
  /// Used for search indexing, OCR comparisons, and text reader drawers.
  final String extractedText;

  /// Optional arbitrary metadata (e.g. column count, baseline row counts, header info).
  final Map<String, dynamic> metadata;

  const PageLayoutSheet({
    required this.pageNumber,
    this.width = 2000,
    this.height = 3200,
    required this.commands,
    this.extractedText = '',
    this.metadata = const {},
  });

  /// Serializes the sheet to a map.
  Map<String, dynamic> toMap() {
    return {
      'pageNumber': pageNumber,
      'width': width,
      'height': height,
      'commands': commands.map((c) => c.toMap()).toList(),
      'extractedText': extractedText,
      'metadata': metadata,
    };
  }

  /// Deserializes a [PageLayoutSheet] from a map.
  factory PageLayoutSheet.fromMap(Map<String, dynamic> map) {
    final rawCommands = (map['commands'] as List<dynamic>?) ?? [];
    return PageLayoutSheet(
      pageNumber: (map['pageNumber'] as num?)?.toInt() ?? 1,
      width: (map['width'] as num?)?.toInt() ?? 2000,
      height: (map['height'] as num?)?.toInt() ?? 3200,
      commands: rawCommands
          .whereType<Map<String, dynamic>>()
          .map(DrawCommand.fromMap)
          .toList(),
      extractedText: (map['extractedText'] ?? '').toString(),
      metadata: Map<String, dynamic>.from(map['metadata'] as Map? ?? {}),
    );
  }

  /// Deserializes a [PageLayoutSheet] from a JSON string.
  factory PageLayoutSheet.fromJson(String source) =>
      PageLayoutSheet.fromMap(jsonDecode(source) as Map<String, dynamic>);

  /// Serializes the sheet to a JSON string.
  String toJson() => jsonEncode(toMap());

  @override
  List<Object?> get props => [
    pageNumber,
    width,
    height,
    commands,
    extractedText,
    metadata,
  ];
}

/// Top-level envelope containing the complete typeset folio sheets and metadata.
/// Acts as the unified contract between the Dart layout engine and rasterization backends.
class PageDisplayList extends Equatable {
  final String fanzineId;
  final String templateId;
  final List<PageLayoutSheet> pages;
  final Map<String, dynamic> metadata;

  const PageDisplayList({
    required this.fanzineId,
    this.templateId = 'basic_text',
    required this.pages,
    this.metadata = const {},
  });

  /// The total number of pages resulting from layout.
  int get pageCount => pages.length;

  /// Aggregates all extracted text across all pages in publication order.
  String get fullExtractedText =>
      pages.map((p) => p.extractedText).where((t) => t.isNotEmpty).join('\n\n');

  /// Serializes the entire display list to a map.
  Map<String, dynamic> toMap() {
    return {
      'fanzineId': fanzineId,
      'templateId': templateId,
      'pageCount': pageCount,
      'pages': pages.map((p) => p.toMap()).toList(),
      'metadata': metadata,
    };
  }

  /// Deserializes a [PageDisplayList] from a map.
  factory PageDisplayList.fromMap(Map<String, dynamic> map) {
    final rawPages = (map['pages'] as List<dynamic>?) ?? [];
    return PageDisplayList(
      fanzineId: (map['fanzineId'] ?? '').toString(),
      templateId: (map['templateId'] ?? 'basic_text').toString(),
      pages: rawPages
          .whereType<Map<String, dynamic>>()
          .map(PageLayoutSheet.fromMap)
          .toList(),
      metadata: Map<String, dynamic>.from(map['metadata'] as Map? ?? {}),
    );
  }

  /// Deserializes a [PageDisplayList] from a JSON string.
  factory PageDisplayList.fromJson(String source) =>
      PageDisplayList.fromMap(jsonDecode(source) as Map<String, dynamic>);

  /// Serializes the entire display list to a JSON string.
  String toJson() => jsonEncode(toMap());

  @override
  List<Object?> get props => [
    fanzineId,
    templateId,
    pages,
    metadata,
  ];
}